    def parse_term() -> float:
        nonlocal i
        val = parse_factor()
        while i < n and s[i] in '*/':
            op = s[i]
            i += 1
            rhs = parse_factor()
            val = val * rhs if op == '*' else val / rhs
        return val

    def parse_factor() -> float:
        return parse_unary()

    def parse_unary() -> float:
        nonlocal i
        if i < n and s[i] == '-':
            i += 1
            return -parse_unary()
        return parse_power()

    def parse_power() -> float:
        nonlocal i
        val = parse_primary()
        if i + 1 < n and s[i] == '*' and s[i + 1] == '*':
            i += 2
            rhs = parse_power()
            val = val ** rhs
        return val

    def parse_primary() -> float:
        nonlocal i
        if i < n and s[i] == '(':
            i += 1
            val = parse_expr()
            if i < n and s[i] == ')':
                i += 1
                return val
            raise ValueError('Missing closing parenthesis')
        start = i
        while i < n and s[i].isdigit():
            i += 1
        if start == i:
            raise ValueError('Expected number')
        return float(s[start:i])

    result = parse_expr()
    if i != n:
        raise ValueError('Unexpected characters')
